module blake2_G(input wire [63 : 0] a,input wire [63 : 0] b,input wire [63 : 0] c,input wire [63 : 0] d,input wire [63 : 0] m0,input wire [63 : 0] m1,output wire [63 : 0] a_prim,output wire [63 : 0] b_prim,output wire [63 : 0] c_prim,output wire [63 : 0] d_prim);

