  reg [63 : 0] internal_b_prim; 
  reg [63 : 0] internal_c_prim; 
  reg [63 : 0] internal_d_prim; 
  assign a_prim = internal_a_prim; 
  assign b_prim = internal_b_prim; 
  assign c_prim = internal_c_prim; 
  assign d_prim = internal_d_prim; 
  always @* 
  begin : G 
  reg [63 : 0] a0; 
  reg [63 : 0] a1; 
  reg [63 : 0] b0; 
  reg [63 : 0] b1; 
  reg [63 : 0] b2; 
  reg [63 : 0] b3; 
  reg [63 : 0] c0; 
