  reg [63 : 0] d0; 
  reg [63 : 0] d1; 
  reg [63 : 0] d2; 
  reg [63 : 0] d3; 
  a0 = a + b + m0; 
  d0 = d ^ a0; 
  d1 = {d0[31 : 0], d0[63 : 32]}; 
  c0 = c + d1; 
  b0 = b ^ c0; 
  b1 = {b0[23 : 0], b0[63 : 24]}; 
  a1 = a0 + b1 + m1; 
  d2 = d1 ^ a1; 
  d3 = {d2[15 : 0], d2[63 : 16]}; 
  c1 = c0 + d3; 
  b2 = b1 ^ c1; 
  b3 = {b2[62 : 0], b2[63]}; 
  internal_a_prim = a1; 
  internal_b_prim = b3; 
  internal_c_prim = c1; 
